questionvariables.text:
/* Generate vectors a and b */
bX:rand(5)+4;
aX:rand(bX-2)+1;
aY:rand(5)+1

/* Generating midpoints X and Y */
midX:rand(["DF","FH","CF","CG","GH","EG"]);
midY:rand(["OA","OB"]);

/* OX */
tans1: if midX="EG" then 1/2 else if midX="CG" then 1 else if (midX="CF" or midX="GH") then 3/2 else if (midX="FH" or midX="DF") then 2;
tans2: if midX="DF" then 1/2 else if midX="CF" then 1 else if (midX="FH" or midX="CG") then 3/2 else if (midX="GH" or midX="EG") then 2;

tans3: sqrt((tans1*aX+tans2*bX)^2+(tans1*aY)^2);

/* YX reflected in DE */
aXref: if midX="EG" or midX="GH" then 0 else if midX="CG" or midX="FH" then 1/2 else if midX="CF" then 1 else 3/2;
bXref: if midX="DF" or midX="FH" then 0 else if midX="CF" or midX="GH" then 1/2 else if midX="CG" then 1 else 3/2;

aYref: if midY="OA" then 2 else 3/2;
bYref: if midY="OA" then 3/2 else 2;

tans4:aXref-aYref;
tans5:bXref-bYref;

tans6: sqrt((4*(bX+aX)^2+4*aY^2)/(4*(bX-aX)^2+4*aY^2));

feedbackvariables.text:
/* Node 1: Check correctness */
node1_test: if ans1=tans1 and ans2=tans2 then 1 else 0;

/* Node 2: Worked solution */

/* Check if a coeff is correct */

/* Check if b coeff is correct */

/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: Check whether answer consistent with (a) */
node3_error: sqrt((ans1*aX+ans2*bX)^2+(ans1*aY)^2);

/* Node 4: Check whether correct answer is given approximately */
node4_test: if tans3-0.1<ans3 and ans3<tans3+0.1 and floatnump(ans3) then 1 else 0;

/* Node 5: Check whether consistent answer is given approximately */
node5_test: if node3_error-0.1<ans3 and ans3<node3_error+0.1 and floatnump(ans3) then 1 else 0;

/* Node 6: Check whether they have just summed magnitudes of a and b times respective constants */
node6_error: ans1*sqrt(aX^2+aY^2) + ans2*bX;

/* Node 1: Check correct answer */
node1_test: if ans4=tans4 and ans5=tans5 then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Check whether found reflection of XY (1) */
node3_test: if ans4=-tans4 and ans5=-tans5 then 1 else 0;

/* Node 4: Check whether either of a or b coeff is correct (1) */
node6_test: if ans4=tans4 or ans5=tans5 then 1 else 0;

/* Node 5: Check whether student has found YX but not reflected (1) */
node5_test: if (midY="OA" and ans4=tans1-1/2 and ans5=tans2) or (midY="OB" and ans4=tans1 and ans5=tans2-1/2) then 1 else 0;

/* Node 6: Check whether student has found YX consistent with (a) but not reflected (1) */
node6_test: if (midY="OA" and ans4=ans1-1/2 and ans5=ans2) or (midY="OB" and ans4=ans1 and ans5=ans2-1/2) then 1 else 0;

/* Node 7: Check whether student has found XY but not reflected */
node7_test: if (midY="OA" and ans4=1/2-tans1 and ans5=tans2) or (midY="OB" and ans4=tans1 and ans5=1/2-tans2) then 1 else 0;

/* Node 8: Check whether student has found XY consistent with (a) but not reflected */
node8_test: if (midY="OA" and ans4=1/2-ans1 and ans5=ans2) or (midY="OB" and ans4=ans1 and ans5=1/2-ans2) then 1 else 0;

/* Node 1: Check correct answer */

/* Node 2: Worked solution */

/* Node 3: Check whether student used incorrect method to find mag(OH) and mag(DE) (summing mag(a) and mag(b) multiplied by coefficients) */
node3_error: (sqrt(aX^2+aY^2)+bX)/(-sqrt(aX^2+aY^2)+bX);
